}.page.active{display:block}.hero{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(280px,.6fr);gap:15px;margin-bottom:15px}.hero-main,.hero-side,.card{border:1px solid var(--line);border-radius:20px;background:#fff;box-shadow:0 8px 30px rgba(0,0,0,.035)}.hero-main{padding:28px;background:linear-gradient(135deg,#fff 0%,#fff7f3 65%,#f3ede5)}.eyebrow{margin:0;color:var(--accent);font-size:9px;font-weight:950;text-transform:uppercase;letter-spacing:.13em}.hero-main h2{margin:8px 0 9px;font-size:clamp(30px,5vw,54px);line-height:.95;letter-spacing:-.055em}.hero-main p:last-child{max-width:700px;margin:0;color:var(--muted);line-height:1.55}.hero-side{padding:20px;display:flex;flex-direction:column;justify-content:space-between}.agent-orb{width:64px;height:64px;display:grid;place-items:center;border-radius:20px;background:radial-gradient(circle at 30% 25%,#ffab8c,#d94a2b 58%,#7e281b);color:#fff;font-size:22px;font-weight:900;box-shadow:0 14px 35px rgba(217,74,43,.25)}.btn{min-height:40px;border:1px solid var(--line);border-radius:10px;padding:9px 12px;background:#fff;color:var(--ink);font-weight:850;font-size:11px;cursor:pointer}.btn.primary{background:var(--accent);border-color:var(--accent);color:#fff}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-bottom:15px}.stat{padding:15px;border:1px solid var(--line);border-radius:16px;background:#fff}.stat small{display:block;color:var(--muted);font-size:8px;text-transform:uppercase;font-weight:900}.stat strong{display:block;margin-top:7px;font-size:22px;letter-spacing:-.04em}.grid{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(280px,.75fr);gap:14px}.card{padding:19px}.card h3{margin:0 0 5px;font-size:15px}.muted{color:var(--muted);font-size:11px;line-height:1.5}.list{display:grid;gap:8px;margin-top:12px}.item{padding:12px;border:1px solid var(--line);border-radius:13px;background:#fff}.itemtop{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.item strong{font-size:12px}.item small{color:var(--muted);font-size:9px}.chip{display:inline-flex;padding:5px 7px;border-radius:999px;background:#f2f1ed;color:#5c625c;font-size:8px;font-weight:900;text-transform:capitalize}.chip.good{background:#eaf7ef;color:#157347}.money{font-size:20px!important}.empty{padding:28px;text-align:center;color:var(--muted);font-size:11px;border:1px dashed #c9cac5;border-radius:13px}.sectionhead{display:flex;align-items:end;justify-content:space-between;gap:14px;margin-bottom:16px}.sectionhead h2{margin:5px 0 0;font-size:34px;letter-spacing:-.045em}.field{width:100%;min-height:41px;padding:9px 11px;border:1px solid var(--line);border-radius:10px;background:#fff}.formgrid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.formgrid .wide{grid-column:1/-1}label{display:block;margin-bottom:5px;font-size:9px;font-weight:900;color:#555b56}.request-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.request-type{padding:14px;border:1px solid var(--line);border-radius:14px;background:#fff;cursor:pointer}.request-type:hover{border-color:#e2a28f}.request-type strong{display:block;font-size:12px}.request-type span{display:block;margin-top:4px;color:var(--muted);font-size:9px}.agent-shell{display:grid;grid-template-rows:auto minmax(420px,1fr) auto;min-height:680px;border:1px solid var(--line);border-radius:22px;background:#fff;overflow:hidden;box-shadow:var(--shadow)}.agent-head{padding:18px 20px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}.messages{padding:20px;overflow:auto;background:#f8f7f3;display:flex;flex-direction:column;gap:12px}.message{max-width:76%;padding:12px 14px;border-radius:15px;background:#fff;border:1px solid var(--line);font-size:12px;line-height:1.55;white-space:pre-wrap}.message.user{align-self:flex-end;background:var(--dark);color:#fff;border-color:var(--dark)}.message small{display:block;margin-top:6px;opacity:.6;font-size:8px}.composer{display:grid;grid-template-columns:1fr auto;gap:8px;padding:12px;border-top:1px solid var(--line)}.composer textarea{resize:none;min-height:46px;max-height:140px}.quick{display:flex;flex-wrap:wrap;gap:6px;margin-top:10px}.quick button{border:1px solid #e6c2b6;border-radius:999px;background:#fff8f5;color:#8c3a25;padding:6px 8px;font-size:9px;font-weight:850;cursor:pointer}.notice{padding:10px 12px;border-radius:11px;background:#fff6df;color:#795900;font-size:10px}.toast{position:fixed;right:20px;bottom:20px;z-index:50;padding:11px 14px;border-radius:11px;background:#171b1a;color:#fff;font-size:11px;box-shadow:var(--shadow)}.hidden{display:none!important}@media(max-width:900px){.app{grid-template-columns:1fr}.side{position:static;height:auto}.nav{grid-template-columns:repeat(3,1fr)}.sidefoot{display:none}.hero,.grid{grid-template-columns:1fr}.stats{grid-template-columns:1fr 1fr}.request-grid{grid-template-columns:1fr}.formgrid{grid-template-columns:1fr}.formgrid .wide{grid-column:auto}}@media(max-width:560px){.nav{grid-template-columns:1fr 1fr}.stats{grid-template-columns:1fr}.content{padding:18px}.top{padding:0 16px}.message{max-width:92%}}
</style></head><body><div class="app"><aside class="side"><div class="brand"><div class="logo">G</div><div><strong>Wholesale Portal</strong><span>Private customer workspace</span></div></div><div class="business"><small>Signed in for</small><strong><?=app_escape((string)$account['business_name'])?></strong></div><nav class="nav"><button class="active" data-page="overview">Overview</button><button data-page="agent">AI Agent</button><button data-page="quotes">Quotes</button><button data-page="orders">Orders</button><button data-page="requests">Requests</button><button data-page="profile">Profile</button></nav><div class="sidefoot">Customer-scoped access only<br>Quotes · Orders · Requests · AI</div></aside><main class="main"><header class="top"><div><h1 id="pageTitle">Wholesale Overview</h1><p id="pageSubtitle">Your relationship, orders, quotes, and next actions.</p></div><a href="logout.php">Sign out</a></header><div class="content">
<section class="page active" id="page-overview"><div class="hero"><div class="hero-main"><p class="eyebrow">Wholesale relationship</p><h2>Everything about your gelato account in one place.</h2><p>Track quotes and orders, request samples or reorders, manage business preferences, and ask your private AI assistant about your account.</p></div><div class="hero-side"><div class="agent-orb">AI</div><div><h3 style="margin:14px 0 5px">Your wholesale Agent</h3><p class="muted">Knows your quotes, orders, preferences, requests, and delivery context — never other customers.</p><button class="btn primary" data-goto="agent">Ask the Agent</button></div></div></div><div class="stats"><div class="stat"><small>Account status</small><strong id="ovStatus">—</strong></div><div class="stat"><small>Open requests</small><strong id="ovRequests">0</strong></div><div class="stat"><small>Active quotes</small><strong id="ovQuotes">0</strong></div><div class="stat"><small>Open orders</small><strong id="ovOrders">0</strong></div></div><div class="grid"><section class="card"><h3>Recent orders</h3><p class="muted">Current fulfillment status for your latest wholesale orders.</p><div class="list" id="overviewOrders"></div></section><aside class="card"><h3>Next actions</h3><p class="muted">Quick ways to work with the wholesale team.</p><div class="list"><button class="btn primary" data-request="reorder">Request a reorder</button><button class="btn" data-request="sample">Request samples</button><button class="btn" data-goto="quotes">Review quotes</button><button class="btn" data-goto="profile">Update preferences</button></div></aside></div></section>
<section class="page" id="page-agent"><div class="sectionhead"><div><p class="eyebrow">Private customer intelligence</p><h2>Wholesale AI Agent</h2></div></div><div class="agent-shell"><div class="agent-head"><div><strong>Account Agent</strong><div class="muted" id="agentReady">Checking AI availability…</div></div><button class="btn" id="clearAgent">Clear view</button></div><div class="messages" id="messages"></div><div><div class="quick"><button data-prompt="What is the status of my latest order?">Latest order</button><button data-prompt="Do I have an active quote?">Active quote</button><button data-prompt="What wholesale requests are still open?">Open requests</button><button data-prompt="Summarize my account preferences.">My preferences</button></div><div class="composer"><textarea class="field" id="agentInput" rows="2" placeholder="Ask about your quote, order, delivery, preferences, or requests..."></textarea><button class="btn primary" id="agentSend">Send</button></div></div></div></section>
<section class="page" id="page-quotes"><div class="sectionhead"><div><p class="eyebrow">Pricing & proposals</p><h2>Quotes</h2></div><button class="btn" data-request="product">Request new pricing</button></div><div class="list" id="quotesList"></div></section>
<section class="page" id="page-orders"><div class="sectionhead"><div><p class="eyebrow">Fulfillment</p><h2>Orders</h2></div><button class="btn primary" data-request="reorder">Request reorder</button></div><div class="list" id="ordersList"></div></section>
<section class="page" id="page-requests"><div class="sectionhead"><div><p class="eyebrow">Buyer requests</p><h2>Requests</h2></div></div><div class="request-grid"><button class="request-type" data-request="reorder"><strong>Reorder</strong><span>Ask the team to repeat or adjust a prior order.</span></button><button class="request-type" data-request="sample"><strong>Samples</strong><span>Request flavors or package samples.</span></button><button class="request-type" data-request="product"><strong>Product / pricing</strong><span>Ask for new flavors, sizes, private label, or a quote.</span></button><button class="request-type" data-request="delivery"><strong>Delivery</strong><span>Ask about delivery timing, pickup, or location details.</span></button><button class="request-type" data-request="support"><strong>Support</strong><span>Send another wholesale account question.</span></button></div><div class="card" style="margin-top:14px"><h3>Request history</h3><div class="list" id="requestsList"></div></div></section>
<section class="page" id="page-profile"><div class="sectionhead"><div><p class="eyebrow">Customer profile</p><h2>Business preferences</h2></div></div><section class="card"><form id="profileForm"><div class="formgrid"><div><label>Phone</label><input class="field" id="pPhone"></div><div><label>Website</label><input class="field" id="pWebsite"></div><div><label>Billing email</label><input class="field" id="pBilling" type="email"></div><div><label>Preferred fulfillment</label><select class="field" id="pFulfillment"><option value="">Not set</option><option>Delivery</option><option>Pickup</option><option>Either</option></select></div><div class="wide"><label>Flavor preferences</label><textarea class="field" id="pFlavors" rows="4"></textarea></div><div class="wide"><label>Package preferences — comma separated</label><input class="field" id="pPackages" placeholder="5L pans, 3-gallon tubs, pints"></div><div class="wide"><label>Customer notes</label><textarea class="field" id="pNotes" rows="4" placeholder="Menu goals, seasonal needs, receiving preferences..."></textarea></div><div class="wide"><label style="display:flex;gap:8px;align-items:center"><input type="checkbox" id="pPrivate"> Interested in private label / custom program</label></div><div class="wide"><button class="btn primary" type="submit">Save profile</button></div></div></form></section><section class="card" style="margin-top:14px"><h3>Locations</h3><div class="list" id="locationsList"></div></section></section>
</div></main></div><div class="toast hidden" id="toast"></div>
<script>window.WHOLESALE_PORTAL={csrf:<?=json_encode(app_csrf_token(),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>};</script><script>
(()=>{const cfg=window.WHOLESALE_PORTAL,$=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c])),money=v=>'$'+Number(v||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});let data=null;const titles={overview:['Wholesale Overview','Your relationship, orders, quotes, and next actions.'],agent:['Wholesale AI Agent','Private account intelligence scoped only to your business.'],quotes:['Quotes','Review pricing and accept active proposals.'],orders:['Orders','Track wholesale fulfillment and delivery status.'],requests:['Requests','Reorders, samples, products, delivery, and support.'],profile:['Business Profile','Keep your wholesale preferences current.']};function toast(t){const e=$('toast');e.textContent=t;e.classList.remove('hidden');setTimeout(()=>e.classList.add('hidden'),2200)}async function api(url,opt={}){const r=await fetch(url,{cache:'no-store',headers:{Accept:'application/json',...(opt.body?{'Content-Type':'application/json','X-CSRF-Token':cfg.csrf}:{}),...(opt.headers||{})},...opt});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'Request failed');return d}function go(p){document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id==='page-'+p));document.querySelectorAll('.nav button').forEach(x=>x.classList.toggle('active',x.dataset.page===p));$('pageTitle').textContent=titles[p][0];$('pageSubtitle').textContent=titles[p][1];if(p==='agent')loadAgent()}document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));document.querySelectorAll('[data-goto]').forEach(b=>b.onclick=()=>go(b.dataset.goto));
function itemLines(items){return (items||[]).map(i=>{if(typeof i==='string')return i;return [i.quantity,i.unit,i.name||i.item||i.product,i.flavor].filter(Boolean).join(' ')}).filter(Boolean).join(' · ')}function render(){const a=data.account,quotes=data.quotes||[],orders=data.orders||[],req=data.requests||[],loc=data.locations||[];$('ovStatus').textContent=a.account_status||'active';$('ovRequests').textContent=req.filter(r=>['new','reviewing'].includes(r.status)).length;$('ovQuotes').textContent=quotes.filter(q=>q.status==='sent').length;$('ovOrders').textContent=orders.filter(o=>!['delivered','cancelled'].includes(o.status)).length;$('overviewOrders').innerHTML=orders.length?orders.slice(0,5).map(orderCard).join(''):'<div class="empty">No orders yet.</div>';$('quotesList').innerHTML=quotes.length?quotes.map(quoteCard).join(''):'<div class="empty">No quotes yet. Request pricing when you are ready.</div>';$('ordersList').innerHTML=orders.length?orders.map(orderCard).join(''):'<div class="empty">No orders yet.</div>';$('requestsList').innerHTML=req.length?req.map(r=>`<article class="item"><div class="itemtop"><div><strong>${esc(r.subject)}</strong><div class="muted">${esc(r.request_type)} · ${esc(r.created_at)}</div></div><span class="chip ${r.status==='closed'?'good':''}">${esc(r.status)}</span></div><p class="muted">${esc(r.details)}</p></article>`).join(''):'<div class="empty">No requests yet.</div>';$('locationsList').innerHTML=loc.length?loc.map(l=>`<article class="item"><strong>${esc(l.name)}</strong><p class="muted">${esc([l.address_line_1,l.address_line_2,l.city,l.state,l.postal_code].filter(Boolean).join(', '))}</p>${l.delivery_notes?`<p class="muted">Delivery: ${esc(l.delivery_notes)}</p>`:''}</article>`).join(''):'<div class="empty">No locations recorded yet.</div>';$('pPhone').value=a.phone||'';$('pWebsite').value=a.website||'';$('pBilling').value=a.billing_email||'';$('pFulfillment').value=a.preferred_fulfillment||'';$('pFlavors').value=a.flavor_preferences||'';$('pPackages').value=(JSON.parse(a.package_preferences_json||'[]')||[]).join(', ');$('pNotes').value=a.customer_notes||'';$('pPrivate').checked=!!Number(a.private_label_interest)}function orderCard(o){return `<article class="item"><div class="itemtop"><div><strong>${esc(o.order_number)}</strong><div class="muted">${esc(itemLines(o.items))}</div></div><div style="text-align:right"><span class="chip ${o.status==='delivered'?'good':''}">${esc(o.status)}</span><strong class="money" style="display:block;margin-top:6px">${money(o.total)}</strong></div></div>${o.promised_for?`<p class="muted">Promised: ${esc(o.promised_for)}</p>`:''}</article>`}function quoteCard(q){const accept=q.status==='sent'?`<button class="btn primary" data-accept="${esc(q.public_id)}">Accept quote</button>`:'';return `<article class="item"><div class="itemtop"><div><strong>${esc(q.quote_number)}</strong><div class="muted">${esc(itemLines(q.items))}</div></div><div style="text-align:right"><span class="chip ${q.status==='accepted'?'good':''}">${esc(q.status)}</span><strong class="money" style="display:block;margin-top:6px">${money(q.total)}</strong></div></div>${q.customer_message?`<p class="muted">${esc(q.customer_message)}</p>`:''}${q.valid_until?`<p class="muted">Valid through ${esc(q.valid_until)}</p>`:''}${accept}</article>`}async function load(){data=await api('api/wholesale-portal.php');render();document.querySelectorAll('[data-accept]').forEach(b=>b.onclick=async()=>{if(!confirm('Accept this quote and create an order request?'))return;try{const d=await api('api/wholesale-portal.php',{method:'POST',body:JSON.stringify({action:'accept_quote',quoteId:b.dataset.accept,csrf_token:cfg.csrf})});toast(d.message);await load()}catch(e){alert(e.message)}})}
function openRequest(type){const labels={reorder:'Reorder request',sample:'Sample request',product:'Product / pricing request',delivery:'Delivery request',support:'Wholesale support'};const subject=prompt(labels[type]+' — short subject');if(!subject)return;const details=prompt('Describe what you need. Include flavors, package sizes, quantities, timing, or order number when relevant.');if(!details)return;api('api/wholesale-portal.php',{method:'POST',body:JSON.stringify({action:'request',requestType:type,subject,details,csrf_token:cfg.csrf})}).then(d=>{toast(d.message);load();go('requests')}).catch(e=>alert(e.message))}document.querySelectorAll('[data-request]').forEach(b=>b.onclick=()=>openRequest(b.dataset.request));$('profileForm').onsubmit=async e=>{e.preventDefault();try{const payload={action:'profile',phone:$('pPhone').value,website:$('pWebsite').value,billingEmail:$('pBilling').value,preferredFulfillment:$('pFulfillment').value,flavorPreferences:$('pFlavors').value,packagePreferences:$('pPackages').value.split(',').map(x=>x.trim()).filter(Boolean),customerNotes:$('pNotes').value,privateLabelInterest:$('pPrivate').checked,csrf_token:cfg.csrf};const d=await api('api/wholesale-portal.php',{method:'POST',body:JSON.stringify(payload)});toast(d.message);await load()}catch(err){alert(err.message)}};
let agentLoaded=false;function addMessage(role,text,meta=''){const m=document.createElement('div');m.className='message '+(role==='user'?'user':'');m.textContent=text;if(meta){const s=document.createElement('small');s.textContent=meta;m.appendChild(s)}$('messages').appendChild(m);$('messages').scrollTop=$('messages').scrollHeight}async function loadAgent(){if(agentLoaded)return;agentLoaded=true;try{const d=await api('api/wholesale-portal-agent.php');$('agentReady').textContent=d.ready?'AI connected · account-scoped':'Account skills available · open-ended AI not configured';$('messages').innerHTML='';if((d.history||[]).length)(d.history||[]).forEach(h=>addMessage(h.message_role,h.content,h.skill||''));else addMessage('assistant',`Welcome. I can help with ${d.businessName}'s quotes, orders, delivery status, requests, and wholesale preferences.`,'wholesale_portal.agent')}catch(e){$('agentReady').textContent=e.message}}async function sendAgent(){const v=$('agentInput').value.trim();if(!v)return;addMessage('user',v);$('agentInput').value='';$('agentSend').disabled=true;try{const d=await api('api/wholesale-portal-agent.php',{method:'POST',body:JSON.stringify({message:v,csrf_token:cfg.csrf})});addMessage('assistant',d.reply,d.skill||'')}catch(e){addMessage('assistant',e.message)}finally{$('agentSend').disabled=false}}$('agentSend').onclick=sendAgent;$('agentInput').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendAgent()}};document.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>{$('agentInput').value=b.dataset.prompt;sendAgent()});$('clearAgent').onclick=()=>{$('messages').innerHTML='';addMessage('assistant','This clears only the current screen. Your secure conversation history remains available when you reload.','portal')};load().catch(e=>alert(e.message));})();
</script></body></html>
